import math

def linear_path(noise, data, t):
    if not noise or len(noise) != len(data) or not 0 <= t <= 1:
        raise ValueError("需要同长非空端点以及 [0,1] 时间")
    if not all(math.isfinite(x) for x in [*noise, *data, t]):
        raise ValueError("输入必须有限")
    xt = [(1-t)*a+t*b for a,b in zip(noise,data)]
    velocity = [b-a for a,b in zip(noise,data)]
    return xt, velocity

def conditional_mean_velocity(velocities, weights):
    if not velocities or len(velocities) != len(weights):
        raise ValueError("配对数量不一致")
    dim = len(velocities[0])
    if dim == 0 or any(len(v) != dim for v in velocities):
        raise ValueError("速度维度不一致")
    if any(w < 0 or not math.isfinite(w) for w in weights) or sum(weights) <= 0:
        raise ValueError("需要非负权重和正总权重")
    if not all(math.isfinite(x) for v in velocities for x in v):
        raise ValueError("速度必须有限")
    total = sum(weights)
    return [sum(w*v[d] for w,v in zip(weights,velocities))/total for d in range(dim)]

