import torch

@torch.no_grad()
def heun_sample(velocity, noise, times, condition):
    if noise.ndim < 2 or not noise.is_floating_point():
        raise ValueError("noise 必须含 Batch 轴且为浮点张量")
    grid = torch.as_tensor(times,dtype=noise.dtype,device=noise.device)
    if grid.ndim != 1 or grid.numel() < 2 or not torch.isfinite(grid).all():
        raise ValueError("需要至少两个有限时间点")
    deltas = grid[1:]-grid[:-1]
    if not ((deltas > 0).all() or (deltas < 0).all()):
        raise ValueError("时间网格必须严格单调")
    x = noise.clone()
    for left,right in zip(grid[:-1],grid[1:]):
        h = right-left
        t0 = x.new_full((x.shape[0],),left.item())
        t1 = x.new_full((x.shape[0],),right.item())
        k1 = velocity(x,t0,condition)
        if k1.shape != x.shape:
            raise ValueError("速度形状必须等于状态形状")
        candidate = x+h*k1
        k2 = velocity(candidate,t1,condition)
        if k2.shape != x.shape:
            raise ValueError("速度形状必须等于状态形状")
        x = x+0.5*h*(k1+k2)
    return x
